53	/**
54	 * An assortment of mainly legacy static utility methods that operate on or return objects of type
55	 * {@code Iterable}. Except as noted, each method has a corresponding {@link Iterator}-based method
56	 * in the {@link Iterators} class.
57	 *
58	 * <p><b>Java 8+ users:</b> several common uses for this class are now more comprehensively
59	 * addressed by the new {@link java.util.stream.Stream} library. Read the method documentation below
60	 * for comparisons. This class is not being deprecated, but we gently encourage you to migrate to
61	 * streams.
62	 *
63	 * <p><i>Performance notes:</i> Unless otherwise noted, all of the iterables produced in this class
64	 * are <i>lazy</i>, which means that their iterators only advance the backing iteration when
65	 * absolutely necessary.
66	 *
67	 * <p>See the Guava User Guide article on <a href=
68	 * "https://github.com/google/guava/wiki/CollectionUtilitiesExplained#iterables">{@code
69	 * Iterables}</a>.
70	 *
71	 * @author Kevin Bourrillion
72	 * @author Jared Levy
73	 * @since 2.0
74	 */
75	@GwtCompatible
76	public final class Iterables {
77	  private Iterables() {}
78	
79	  /** Returns an unmodifiable view of {@code iterable}. */
80	  public static <T extends @Nullable Object> Iterable<T> unmodifiableIterable(
81	      Iterable<? extends T> iterable) {
82	    checkNotNull(iterable);
83	    if (iterable instanceof UnmodifiableIterable || iterable instanceof ImmutableCollection) {
84	      @SuppressWarnings("unchecked") // Since it's unmodifiable, the covariant cast is safe
85	      Iterable<T> result = (Iterable<T>) iterable;
86	      return result;
87	    }
88	    return new UnmodifiableIterable<>(iterable);
89	  }
90	
91	  /**
92	   * Simply returns its argument.
93	   *
94	   * @deprecated no need to use this
95	   * @since 10.0
96	   */
97	  @InlineMe(
98	      replacement = "checkNotNull(iterable)",
99	      staticImports = "com.google.common.base.Preconditions.checkNotNull")
100	  @Deprecated
101	  public static <E> Iterable<E> unmodifiableIterable(ImmutableCollection<E> iterable) {
102	    return checkNotNull(iterable);
103	  }
104	
105	  private static final class UnmodifiableIterable<T extends @Nullable Object>
106	      extends FluentIterable<T> {
107	    private final Iterable<? extends T> iterable;
108	
109	    private UnmodifiableIterable(Iterable<? extends T> iterable) {
110	      this.iterable = iterable;
111	    }
112	
113	    @Override
114	    public Iterator<T> iterator() {
115	      return unmodifiableIterator(iterable.iterator());
116	    }
117	
118	    @Override
119	    public void forEach(Consumer<? super T> action) {
120	      iterable.forEach(action);
121	    }
122	
123	    @SuppressWarnings("unchecked") // safe upcast, assuming no one has a crazy Spliterator subclass
124	    @Override
125	    public Spliterator<T> spliterator() {
126	      return (Spliterator<T>) iterable.spliterator();
127	    }
128	
129	    @Override
130	    public String toString() {
131	      return iterable.toString();
132	    }
133	    // no equals and hashCode; it would break the contract!
134	  }
135	
136	  /** Returns the number of elements in {@code iterable}. */
137	  public static int size(Iterable<?> iterable) {
138	    return (iterable instanceof Collection)
139	        ? ((Collection<?>) iterable).size()
140	        : Iterators.size(iterable.iterator());
141	  }
142	
143	  /**
144	   * Returns {@code true} if {@code iterable} contains any element {@code o} for which {@code
145	   * Objects.equals(o, element)} would return {@code true}. Otherwise returns {@code false}, even in
146	   * cases where {@link Collection#contains} might throw {@link NullPointerException} or {@link
147	   * ClassCastException}.
148	   */
149	  public static boolean contains(Iterable<?> iterable, @Nullable Object element) {
150	    if (iterable instanceof Collection) {
151	      Collection<?> collection = (Collection<?>) iterable;
152	      return safeContains(collection, element);
153	    }
154	    return Iterators.contains(iterable.iterator(), element);
155	  }
156	
157	  /**
158	   * Removes, from an iterable, every element that belongs to the provided collection.
159	   *
160	   * <p>This method calls {@link Collection#removeAll} if {@code iterable} is a collection, and
161	   * {@link Iterators#removeAll} otherwise.
162	   *
163	   * @param removeFrom the iterable to (potentially) remove elements from
164	   * @param elementsToRemove the elements to remove
165	   * @return {@code true} if any element was removed from {@code iterable}
166	   */
167	  @CanIgnoreReturnValue
168	  public static boolean removeAll(Iterable<?> removeFrom, Collection<?> elementsToRemove) {
169	    return (removeFrom instanceof Collection)
170	        ? ((Collection<?>) removeFrom).removeAll(checkNotNull(elementsToRemove))
171	        : Iterators.removeAll(removeFrom.iterator(), elementsToRemove);
172	  }
173	
174	  /**
175	   * Removes, from an iterable, every element that does not belong to the provided collection.
176	   *
177	   * <p>This method calls {@link Collection#retainAll} if {@code iterable} is a collection, and
178	   * {@link Iterators#retainAll} otherwise.
179	   *
180	   * @param removeFrom the iterable to (potentially) remove elements from
181	   * @param elementsToRetain the elements to retain
182	   * @return {@code true} if any element was removed from {@code iterable}
183	   */
184	  @CanIgnoreReturnValue
185	  public static boolean retainAll(Iterable<?> removeFrom, Collection<?> elementsToRetain) {
186	    return (removeFrom instanceof Collection)
187	        ? ((Collection<?>) removeFrom).retainAll(checkNotNull(elementsToRetain))
188	        : Iterators.retainAll(removeFrom.iterator(), elementsToRetain);
189	  }
190	
191	  /**
192	   * Removes, from an iterable, every element that satisfies the provided predicate.
193	   *
194	   * <p>Removals may or may not happen immediately as each element is tested against the predicate.
195	   * The behavior of this method is not specified if {@code predicate} is dependent on {@code
196	   * removeFrom}.
197	   *
198	   * <p><b>Java 8+ users:</b> if {@code removeFrom} is a {@link Collection}, use {@code
199	   * removeFrom.removeIf(predicate)} instead.
200	   *
201	   * @param removeFrom the iterable to (potentially) remove elements from
202	   * @param predicate a predicate that determines whether an element should be removed
203	   * @return {@code true} if any elements were removed from the iterable
204	   * @throws UnsupportedOperationException if the iterable does not support {@code remove()}.
205	   * @since 2.0
206	   */
207	  @CanIgnoreReturnValue
208	  public static <T extends @Nullable Object> boolean removeIf(
209	      Iterable<T> removeFrom, Predicate<? super T> predicate) {
210	    if (removeFrom instanceof Collection) {
211	      return ((Collection<T>) removeFrom).removeIf(predicate);
212	    }
213	    return Iterators.removeIf(removeFrom.iterator(), predicate);
214	  }
215	
216	  /** Removes and returns the first matching element, or returns {@code null} if there is none. */
217	  static <T extends @Nullable Object> @Nullable T removeFirstMatching(
218	      Iterable<T> removeFrom, Predicate<? super T> predicate) {
219	    checkNotNull(predicate);
220	    Iterator<T> iterator = removeFrom.iterator();
221	    while (iterator.hasNext()) {
222	      T next = iterator.next();
223	      if (predicate.apply(next)) {
224	        iterator.remove();
225	        return next;
226	      }
227	    }
228	    return null;
229	  }
230	
231	  /**
232	   * Determines whether two iterables contain equal elements in the same order. More specifically,
233	   * this method returns {@code true} if {@code iterable1} and {@code iterable2} contain the same
234	   * number of elements and every element of {@code iterable1} is equal to the corresponding element
235	   * of {@code iterable2}.
236	   */
237	  public static boolean elementsEqual(Iterable<?> iterable1, Iterable<?> iterable2) {
238	    if (iterable1 instanceof Collection && iterable2 instanceof Collection) {
239	      Collection<?> collection1 = (Collection<?>) iterable1;
240	      Collection<?> collection2 = (Collection<?>) iterable2;
241	      if (collection1.size() != collection2.size()) {
242	        return false;
243	      }
244	    }
245	    return Iterators.elementsEqual(iterable1.iterator(), iterable2.iterator());
246	  }
247	
248	  /**
249	   * Returns a string representation of {@code iterable}, with the format {@code [e1, e2, ..., en]}
250	   * (that is, identical to {@link java.util.Arrays Arrays}{@code
251	   * .toString(Iterables.toArray(iterable))}). Note that for <i>most</i> implementations of {@link
252	   * Collection}, {@code collection.toString()} also gives the same result, but that behavior is not
253	   * generally guaranteed.
254	   */
255	  public static String toString(Iterable<?> iterable) {
256	    return Iterators.toString(iterable.iterator());
257	  }
258	
259	  /**
260	   * Returns the single element contained in {@code iterable}.
261	   *
262	   * <p><b>Java 8+ users:</b> the {@code Stream} equivalent to this method is {@code
263	   * stream.collect(MoreCollectors.onlyElement())}.
264	   *
265	   * @throws NoSuchElementException if the iterable is empty
266	   * @throws IllegalArgumentException if the iterable contains multiple elements
267	   */
268	  @ParametricNullness
269	  public static <T extends @Nullable Object> T getOnlyElement(Iterable<T> iterable) {
270	    return Iterators.getOnlyElement(iterable.iterator());
271	  }
272	
273	  /**
274	   * Returns the single element contained in {@code iterable}, or {@code defaultValue} if the
275	   * iterable is empty.
276	   *
277	   * <p><b>Java 8+ users:</b> the {@code Stream} equivalent to this method is {@code
278	   * stream.collect(MoreCollectors.toOptional()).orElse(defaultValue)}.
279	   *
280	   * @throws IllegalArgumentException if the iterator contains multiple elements
281	   */
282	  @ParametricNullness
283	  public static <T extends @Nullable Object> T getOnlyElement(
284	      Iterable<? extends T> iterable, @ParametricNullness T defaultValue) {
285	    return Iterators.getOnlyElement(iterable.iterator(), defaultValue);
286	  }
287	
288	  /**
289	   * Copies an iterable's elements into an array.
290	   *
291	   * @param iterable the iterable to copy
292	   * @param type the type of the elements
293	   * @return a newly-allocated array into which all the elements of the iterable have been copied
294	   */
295	  @GwtIncompatible // Array.newInstance(Class, int)
296	  public static <T extends @Nullable Object> T[] toArray(
297	      Iterable<? extends T> iterable, Class<@NonNull T> type) {
298	    return toArray(iterable, ObjectArrays.newArray(type, 0));
299	  }
300	
301	  static <T extends @Nullable Object> T[] toArray(Iterable<? extends T> iterable, T[] array) {
302	    Collection<? extends T> collection = castOrCopyToCollection(iterable);
303	    return collection.toArray(array);
304	  }
305	
306	  /**
307	   * Copies an iterable's elements into an array.
308	   *
309	   * @param iterable the iterable to copy
310	   * @return a newly-allocated array into which all the elements of the iterable have been copied
311	   */
312	  static @Nullable Object[] toArray(Iterable<?> iterable) {
313	    return castOrCopyToCollection(iterable).toArray();
314	  }
315	
316	  /**
317	   * Converts an iterable into a collection. If the iterable is already a collection, it is
318	   * returned. Otherwise, an {@link java.util.ArrayList} is created with the contents of the
319	   * iterable in the same iteration order.
320	   */
321	  private static <E extends @Nullable Object> Collection<E> castOrCopyToCollection(
322	      Iterable<E> iterable) {
323	    return (iterable instanceof Collection)
324	        ? (Collection<E>) iterable
325	        : newArrayList(iterable.iterator());
326	  }
327	
328	  /**
329	   * Adds all elements in {@code iterable} to {@code collection}.
330	   *
331	   * @return {@code true} if {@code collection} was modified as a result of this operation.
332	   */
333	  @CanIgnoreReturnValue
334	  public static <T extends @Nullable Object> boolean addAll(
335	      Collection<T> addTo, Iterable<? extends T> elementsToAdd) {
336	    if (elementsToAdd instanceof Collection) {
337	      Collection<? extends T> c = (Collection<? extends T>) elementsToAdd;
338	      return addTo.addAll(c);
339	    }
340	    return Iterators.addAll(addTo, checkNotNull(elementsToAdd).iterator());
341	  }
342	
343	  /**
344	   * Returns the number of elements in the specified iterable that equal the specified object. This
345	   * implementation avoids a full iteration when the iterable is a {@link Multiset} or {@link Set}.
346	   *
347	   * <p><b>Java 8+ users:</b> In most cases, the {@code Stream} equivalent of this method is {@code
348	   * stream.filter(element::equals).count()}. If {@code element} might be null, use {@code
349	   * stream.filter(Predicate.isEqual(element)).count()} instead.
350	   *
351	   * @see java.util.Collections#frequency(Collection, Object) Collections.frequency(Collection,
352	   *     Object)
353	   */
354	  public static int frequency(Iterable<?> iterable, @Nullable Object element) {
355	    if ((iterable instanceof Multiset)) {
356	      return ((Multiset<?>) iterable).count(element);
357	    } else if ((iterable instanceof Set)) {
358	      return ((Set<?>) iterable).contains(element) ? 1 : 0;
359	    }
360	    return Iterators.frequency(iterable.iterator(), element);
361	  }
362	
363	  /**
364	   * Returns an iterable whose iterators cycle indefinitely over the elements of {@code iterable}.
365	   *
366	   * <p>That iterator supports {@code remove()} if {@code iterable.iterator()} does. After {@code
367	   * remove()} is called, subsequent cycles omit the removed element, which is no longer in {@code
368	   * iterable}. The iterator's {@code hasNext()} method returns {@code true} until {@code iterable}
369	   * is empty.
370	   *
371	   * <p><b>Warning:</b> Typical uses of the resulting iterator may produce an infinite loop. You
372	   * should use an explicit {@code break} or be certain that you will eventually remove all the
373	   * elements.
374	   *
375	   * <p>To cycle over the iterable {@code n} times, use the following: {@code
376	   * Iterables.concat(Collections.nCopies(n, iterable))}
377	   *
378	   * <p><b>Java 8+ users:</b> The {@code Stream} equivalent of this method is {@code
379	   * Stream.generate(() -> iterable).flatMap(Streams::stream)}.
380	   */
381	  public static <T extends @Nullable Object> Iterable<T> cycle(Iterable<T> iterable) {
382	    checkNotNull(iterable);
383	    return new FluentIterable<T>() {
384	      @Override
385	      public Iterator<T> iterator() {
386	        return Iterators.cycle(iterable);
387	      }
388	
389	      @Override
390	      public Spliterator<T> spliterator() {
391	        return Stream.generate(() -> iterable).<T>flatMap(Streams::stream).spliterator();
392	      }
393	
394	      @Override
395	      public String toString() {
396	        return iterable.toString() + " (cycled)";
397	      }
398	    };
399	  }
400	
401	  /**
402	   * Returns an iterable whose iterators cycle indefinitely over the provided elements.
403	   *
404	   * <p>After {@code remove} is invoked on a generated iterator, the removed element will no longer
405	   * appear in either that iterator or any other iterator created from the same source iterable.
406	   * That is, this method behaves exactly as {@code Iterables.cycle(Lists.newArrayList(elements))}.
407	   * The iterator's {@code hasNext} method returns {@code true} until all of the original elements
408	   * have been removed.
409	   *
410	   * <p><b>Warning:</b> Typical uses of the resulting iterator may produce an infinite loop. You
411	   * should use an explicit {@code break} or be certain that you will eventually remove all the
412	   * elements.
413	   *
414	   * <p>To cycle over the elements {@code n} times, use the following: {@code
415	   * Iterables.concat(Collections.nCopies(n, Arrays.asList(elements)))}
416	   *
417	   * <p><b>Java 8+ users:</b> If passing a single element {@code e}, the {@code Stream} equivalent
418	   * of this method is {@code Stream.generate(() -> e)}. Otherwise, put the elements in a collection
419	   * and use {@code Stream.generate(() -> collection).flatMap(Collection::stream)}.
420	   */
421	  @SafeVarargs
422	  public static <T extends @Nullable Object> Iterable<T> cycle(T... elements) {
423	    return cycle(newArrayList(elements));
424	  }
425	
426	  /**
427	   * Combines two iterables into a single iterable. The returned iterable has an iterator that
428	   * traverses the elements in {@code a}, followed by the elements in {@code b}. The source
429	   * iterators are not polled until necessary.
430	   *
431	   * <p>The returned iterable's iterator supports {@code remove()} when the corresponding input
432	   * iterator supports it.
433	   *
434	   * <p><b>Java 8+ users:</b> The {@code Stream} equivalent of this method is {@code
435	   * Stream.concat(a, b)}.
436	   */
437	  public static <T extends @Nullable Object> Iterable<T> concat(
438	      Iterable<? extends T> a, Iterable<? extends T> b) {
439	    return FluentIterable.concat(a, b);
440	  }
441	
442	  /**
443	   * Combines three iterables into a single iterable. The returned iterable has an iterator that
444	   * traverses the elements in {@code a}, followed by the elements in {@code b}, followed by the
445	   * elements in {@code c}. The source iterators are not polled until necessary.
446	   *
447	   * <p>The returned iterable's iterator supports {@code remove()} when the corresponding input
448	   * iterator supports it.
449	   *
450	   * <p><b>Java 8+ users:</b> The {@code Stream} equivalent of this method is {@code
451	   * Streams.concat(a, b, c)}.
452	   */
453	  public static <T extends @Nullable Object> Iterable<T> concat(
454	      Iterable<? extends T> a, Iterable<? extends T> b, Iterable<? extends T> c) {
455	    return FluentIterable.concat(a, b, c);
456	  }
457	
458	  /**
459	   * Combines four iterables into a single iterable. The returned iterable has an iterator that
460	   * traverses the elements in {@code a}, followed by the elements in {@code b}, followed by the
461	   * elements in {@code c}, followed by the elements in {@code d}. The source iterators are not
462	   * polled until necessary.
463	   *
464	   * <p>The returned iterable's iterator supports {@code remove()} when the corresponding input
465	   * iterator supports it.
466	   *
467	   * <p><b>Java 8+ users:</b> The {@code Stream} equivalent of this method is {@code
468	   * Streams.concat(a, b, c, d)}.
469	   */
470	  public static <T extends @Nullable Object> Iterable<T> concat(
471	      Iterable<? extends T> a,
472	      Iterable<? extends T> b,
473	      Iterable<? extends T> c,
474	      Iterable<? extends T> d) {
475	    return FluentIterable.concat(a, b, c, d);
476	  }
477	
478	  /**
479	   * Combines multiple iterables into a single iterable. The returned iterable has an iterator that
480	   * traverses the elements of each iterable in {@code inputs}. The input iterators are not polled
481	   * until necessary.
482	   *
483	   * <p>The returned iterable's iterator supports {@code remove()} when the corresponding input
484	   * iterator supports it.
485	   *
486	   * <p><b>Java 8+ users:</b> The {@code Stream} equivalent of this method is {@code
487	   * Streams.concat(...)}.
488	   *
489	   * @throws NullPointerException if any of the provided iterables is null
490	   */
491	  @SafeVarargs
492	  public static <T extends @Nullable Object> Iterable<T> concat(Iterable<? extends T>... inputs) {
493	    return FluentIterable.concat(inputs);
494	  }
495	
496	  /**
497	   * Combines multiple iterables into a single iterable. The returned iterable has an iterator that
498	   * traverses the elements of each iterable in {@code inputs}. The input iterators are not polled
499	   * until necessary.
500	   *
501	   * <p>The returned iterable's iterator supports {@code remove()} when the corresponding input
502	   * iterator supports it. The methods of the returned iterable may throw {@code
503	   * NullPointerException} if any of the input iterators is null.
504	   *
505	   * <p><b>Java 8+ users:</b> The {@code Stream} equivalent of this method is {@code
506	   * streamOfStreams.flatMap(s -> s)}.
507	   */
508	  public static <T extends @Nullable Object> Iterable<T> concat(
509	      Iterable<? extends Iterable<? extends T>> inputs) {
510	    return FluentIterable.concat(inputs);
511	  }
512	
513	  /**
514	   * Divides an iterable into unmodifiable sublists of the given size (the final iterable may be
515	   * smaller). For example, partitioning an iterable containing {@code [a, b, c, d, e]} with a
516	   * partition size of 3 yields {@code [[a, b, c], [d, e]]} -- an outer iterable containing two
517	   * inner lists of three and two elements, all in the original order.
518	   *
519	   * <p>Iterators returned by the returned iterable do not support the {@link Iterator#remove()}
520	   * method. The returned lists implement {@link RandomAccess}, whether or not the input list does.
521	   *
522	   * <p><b>Note:</b> The current implementation eagerly allocates storage for {@code size} elements.
523	   * As a consequence, passing values like {@code Integer.MAX_VALUE} can lead to {@link
524	   * OutOfMemoryError}.
525	   *
526	   * <p><b>Note:</b> if {@code iterable} is a {@link List}, use {@link Lists#partition(List, int)}
527	   * instead.
528	   *
529	   * @param iterable the iterable to return a partitioned view of
530	   * @param size the desired size of each partition (the last may be smaller)
531	   * @return an iterable of unmodifiable lists containing the elements of {@code iterable} divided
532	   *     into partitions
533	   * @throws IllegalArgumentException if {@code size} is nonpositive
534	   */
535	  public static <T extends @Nullable Object> Iterable<List<T>> partition(
536	      Iterable<T> iterable, int size) {
537	    checkNotNull(iterable);
538	    checkArgument(size > 0);
539	    return new FluentIterable<List<T>>() {
540	      @Override
541	      public Iterator<List<T>> iterator() {
542	        return Iterators.partition(iterable.iterator(), size);
543	      }
544	    };
545	  }
546	
547	  /**
548	   * Divides an iterable into unmodifiable sublists of the given size, padding the final iterable
549	   * with null values if necessary. For example, partitioning an iterable containing {@code [a, b,
550	   * c, d, e]} with a partition size of 3 yields {@code [[a, b, c], [d, e, null]]} -- an outer
551	   * iterable containing two inner lists of three elements each, all in the original order.
552	   *
553	   * <p>Iterators returned by the returned iterable do not support the {@link Iterator#remove()}
554	   * method.
555	   *
556	   * @param iterable the iterable to return a partitioned view of
557	   * @param size the desired size of each partition
558	   * @return an iterable of unmodifiable lists containing the elements of {@code iterable} divided
