887	      Iterable<? extends T> iterable, @ParametricNullness T defaultValue) {
888	    if (iterable instanceof Collection) {
889	      Collection<? extends T> c = (Collection<? extends T>) iterable;
890	      if (c.isEmpty()) {
891	        return defaultValue;
