907	  /**
908	   * Returns a view of {@code iterable} that skips its first {@code numberToSkip} elements. If
909	   * {@code iterable} contains fewer than {@code numberToSkip} elements, the returned iterable skips
910	   * all of its elements.
911	   *
912	   * <p>Modifications to the underlying {@link Iterable} before a call to {@code iterator()} are
913	   * reflected in the returned iterator. That is, the iterator skips the first {@code numberToSkip}
914	   * elements that exist when the {@code Iterator} is created, not when {@code skip()} is called.
915	   *
916	   * <p>The returned iterable's iterator supports {@code remove()} if the iterator of the underlying
917	   * iterable supports it. Note that it is <i>not</i> possible to delete the last skipped element by
918	   * immediately calling {@code remove()} on that iterator, as the {@code Iterator} contract states
919	   * that a call to {@code remove()} before a call to {@code next()} will throw an {@link
920	   * IllegalStateException}.
921	   *
922	   * <p><b>{@code Stream} equivalent:</b> {@link Stream#skip}
923	   *
924	   * @since 3.0
925	   */
926	  public static <T extends @Nullable Object> Iterable<T> skip(
927	      Iterable<T> iterable, int numberToSkip) {
928	    checkNotNull(iterable);
929	    checkArgument(numberToSkip >= 0, "number to skip cannot be negative");
930	
931	    return new FluentIterable<T>() {
932	      @Override
933	      public Iterator<T> iterator() {
934	        if (iterable instanceof List) {
935	          List<T> list = (List<T>) iterable;
936	          int toSkip = Math.min(list.size(), numberToSkip);
937	          return list.subList(toSkip, list.size()).iterator();
938	        }
939	        Iterator<T> iterator = iterable.iterator();
940	
941	        advance(iterator, numberToSkip);
942	
943	        /*
944	         * We can't just return the iterator because an immediate call to its
945	         * remove() method would remove one of the skipped elements instead of
946	         * throwing an IllegalStateException.
947	         */
948	        return new Iterator<T>() {
949	          boolean atStart = true;
950	
951	          @Override
952	          public boolean hasNext() {
953	            return iterator.hasNext();
954	          }
955	
956	          @Override
957	          @ParametricNullness
958	          public T next() {
959	            T result = iterator.next();
960	            atStart = false; // not called if next() fails
961	            return result;
962	          }
963	
964	          @Override
965	          public void remove() {
966	            checkRemove(!atStart);
967	            iterator.remove();
968	          }
969	        };
970	      }
971	
972	      @Override
973	      public Spliterator<T> spliterator() {
974	        if (iterable instanceof List) {
975	          List<T> list = (List<T>) iterable;
976	          int toSkip = Math.min(list.size(), numberToSkip);
977	          return list.subList(toSkip, list.size()).spliterator();
978	        } else {
979	          return Streams.stream(iterable).skip(numberToSkip).spliterator();
980	        }
981	      }
982	    };
983	  }
