1072	  /**
1073	   * Returns an iterable over the merged contents of all given {@code iterables}. Equivalent entries
1074	   * will not be de-duplicated.
1075	   *
1076	   * <p>Callers must ensure that the source {@code iterables} are in non-descending order as this
1077	   * method does not sort its input.
1078	   *
1079	   * <p>For any equivalent elements across all {@code iterables}, elements are returned in the order
1080	   * of their source iterables. That is, if element A from iterable 1 and element B from iterable 2
1081	   * compare as equal, A will be returned before B if iterable 1 was passed before iterable 2.
1082	   *
1083	   * @since 11.0
1084	   */
1085	  public static <T extends @Nullable Object> Iterable<T> mergeSorted(
1086	      Iterable<? extends Iterable<? extends T>> iterables, Comparator<? super T> comparator) {
1087	    checkNotNull(iterables, "iterables");
1088	    checkNotNull(comparator, "comparator");
1089	    Iterable<T> iterable =
1090	        new FluentIterable<T>() {
1091	          @Override
1092	          public Iterator<T> iterator() {
1093	            return Iterators.mergeSorted(
1094	                Iterables.transform(iterables, Iterable::iterator), comparator);
1095	          }
1096	        };
1097	    return new UnmodifiableIterable<>(iterable);
1098	  }
