181	  /** Returns {@code true} if {@code iterator} contains {@code element}. */
182	  public static boolean contains(Iterator<?> iterator, @Nullable Object element) {
183	    if (element == null) {
184	      while (iterator.hasNext()) {
185	        if (iterator.next() == null) {
186	          return true;
187	        }
188	      }
189	    } else {
190	      while (iterator.hasNext()) {
191	        if (element.equals(iterator.next())) {
192	          return true;
193	        }
194	      }
195	    }
196	    return false;
197	  }
