628	  private static <T extends @Nullable Object> UnmodifiableIterator<List<@Nullable T>> partitionImpl(
629	      Iterator<T> iterator, int size, boolean pad) {
630	    checkNotNull(iterator);
631	    checkArgument(size > 0);
632	    return new UnmodifiableIterator<List<@Nullable T>>() {
633	      @Override
634	      public boolean hasNext() {
635	        return iterator.hasNext();
636	      }
637	
638	      @Override
639	      public List<@Nullable T> next() {
640	        if (!hasNext()) {
641	          throw new NoSuchElementException();
642	        }
643	        @SuppressWarnings("unchecked") // we only put Ts in it
644	        @Nullable T[] array = (@Nullable T[]) new Object[size];
645	        int count = 0;
646	        for (; count < size && iterator.hasNext(); count++) {
647	          array[count] = iterator.next();
648	        }
