1176	  /** Implementation of PeekingIterator that avoids peeking unless necessary. */
1177	  private static final class PeekingImpl<E extends @Nullable Object> implements PeekingIterator<E> {
1178	
1179	    private final Iterator<? extends E> iterator;
1180	    private boolean hasPeeked;
1181	    private @Nullable E peekedElement;
1182	
1183	    PeekingImpl(Iterator<? extends E> iterator) {
1184	      this.iterator = checkNotNull(iterator);
1185	    }
1186	
1187	    @Override
1188	    public boolean hasNext() {
1189	      return hasPeeked || iterator.hasNext();
1190	    }
1191	
1192	    @Override
1193	    @ParametricNullness
1194	    public E next() {
1195	      if (!hasPeeked) {
1196	        return iterator.next();
1197	      }
1198	      // The cast is safe because of the hasPeeked check.
1199	      E result = uncheckedCastNullableTToT(peekedElement);
1200	      hasPeeked = false;
1201	      peekedElement = null;
1202	      return result;
1203	    }
1204	
1205	    @Override
1206	    public void remove() {
1207	      checkState(!hasPeeked, "Can't remove after you've peeked at next");
1208	      iterator.remove();
1209	    }
1210	
1211	    @Override
1212	    @ParametricNullness
1213	    public E peek() {
1214	      if (!hasPeeked) {
1215	        peekedElement = iterator.next();
1216	        hasPeeked = true;
1217	      }
1218	      // The cast is safe because of the hasPeeked check.
1219	      return uncheckedCastNullableTToT(peekedElement);
1220	    }
1221	  }
