148	  public static <K extends Enum<K>, V> ImmutableMap<K, V> immutableEnumMap(
149	      Map<K, ? extends V> map) {
150	    if (map instanceof ImmutableEnumMap) {
151	      @SuppressWarnings("unchecked") // safe covariant cast
152	      ImmutableEnumMap<K, V> result = (ImmutableEnumMap<K, V>) map;
153	      return result;
154	    }
155	    Iterator<? extends Entry<K, ? extends V>> entryItr = map.entrySet().iterator();
156	    if (!entryItr.hasNext()) {
157	      return ImmutableMap.of();
158	    }
159	    Entry<K, ? extends V> entry1 = entryItr.next();
160	    K key1 = entry1.getKey();
161	    V value1 = entry1.getValue();
162	    checkEntryNotNull(key1, value1);
163	    // Do something that works for j2cl, where we can't call getDeclaredClass():
164	    EnumMap<K, V> enumMap = new EnumMap<>(singletonMap(key1, value1));
165	    while (entryItr.hasNext()) {
166	      Entry<K, ? extends V> entry = entryItr.next();
167	      K key = entry.getKey();
168	      V value = entry.getValue();
169	      checkEntryNotNull(key, value);
170	      enumMap.put(key, value);
171	    }
172	    return ImmutableEnumMap.asImmutable(enumMap);
