273	  /**
274	   * Returns a capacity that is sufficient to keep the map from being resized as long as it grows no
275	   * larger than expectedSize and the load factor is ≥ its default (0.75).
276	   */
277	  static int capacity(int expectedSize) {
278	    if (expectedSize < 3) {
279	      checkNonnegative(expectedSize, "expectedSize");
280	      return expectedSize + 1;
281	    }
282	    if (expectedSize < Ints.MAX_POWER_OF_TWO) {
283	      // This seems to be consistent across JDKs. The capacity argument to HashMap and LinkedHashMap
284	      // ends up being used to compute a "threshold" size, beyond which the internal table
285	      // will be resized. That threshold is ceilingPowerOfTwo(capacity*loadFactor), where
286	      // loadFactor is 0.75 by default. So with the calculation here we ensure that the
287	      // threshold is equal to ceilingPowerOfTwo(expectedSize). There is a separate code
288	      // path when the first operation on the new map is putAll(otherMap). There, prior to
289	      // https://github.com/openjdk/jdk/commit/3e393047e12147a81e2899784b943923fc34da8e, a bug
290	      // meant that sometimes a too-large threshold is calculated. However, this new threshold is
291	      // independent of the initial capacity, except that it won't be lower than the threshold
292	      // computed from that capacity. Because the internal table is only allocated on the first
293	      // write, we won't see copying because of the new threshold. So it is always OK to use the
294	      // calculation here.
295	      return (int) ceil(expectedSize / 0.75);
296	    }
297	    return Integer.MAX_VALUE; // any large value
298	  }
