483	  /**
484	   * Computes the difference between two maps. This difference is an immutable snapshot of the state
485	   * of the maps at the time this method is called. It will never change, even if the maps change at
486	   * a later time.
487	   *
488	   * <p>Since this method uses {@code HashMap} instances internally, the keys of the supplied maps
489	   * must be well-behaved with respect to {@link Object#equals} and {@link Object#hashCode}.
490	   *
491	   * <p><b>Note:</b>If you only need to know whether two maps have the same mappings, call {@code
492	   * left.equals(right)} instead of this method.
493	   *
494	   * @param left the map to treat as the "left" map for purposes of comparison
495	   * @param right the map to treat as the "right" map for purposes of comparison
496	   * @return the difference between the two maps
497	   */
498	  public static <K extends @Nullable Object, V extends @Nullable Object>
499	      MapDifference<K, V> difference(
500	          Map<? extends K, ? extends V> left, Map<? extends K, ? extends V> right) {

500	          Map<? extends K, ? extends V> left, Map<? extends K, ? extends V> right) {
501	    if (left instanceof SortedMap) {
502	      @SuppressWarnings("unchecked")
503	      SortedMap<K, ? extends V> sortedLeft = (SortedMap<K, ? extends V>) left;
504	      return difference(sortedLeft, right);
505	    }
506	    return difference(left, right, Equivalence.equals());
507	  }
