509	  /**
510	   * Computes the difference between two maps. This difference is an immutable snapshot of the state
511	   * of the maps at the time this method is called. It will never change, even if the maps change at
512	   * a later time.
513	   *
514	   * <p>Since this method uses {@code HashMap} instances internally, the keys of the supplied maps
515	   * must be well-behaved with respect to {@link Object#equals} and {@link Object#hashCode}.
516	   *
517	   * @param left the map to treat as the "left" map for purposes of comparison
518	   * @param right the map to treat as the "right" map for purposes of comparison
519	   * @param valueEquivalence the equivalence relationship to use to compare values
520	   * @return the difference between the two maps
521	   * @since 10.0
522	   */
523	  public static <K extends @Nullable Object, V extends @Nullable Object>
524	      MapDifference<K, V> difference(
525	          Map<? extends K, ? extends V> left,
526	          Map<? extends K, ? extends V> right,
527	          Equivalence<? super @NonNull V> valueEquivalence) {
528	    Preconditions.checkNotNull(valueEquivalence);
529	
530	    Map<K, V> onlyOnLeft = new LinkedHashMap<>();
531	    Map<K, V> onlyOnRight = new LinkedHashMap<>(right); // will whittle it down
532	    Map<K, V> onBoth = new LinkedHashMap<>();
533	    Map<K, ValueDifference<V>> differences = new LinkedHashMap<>();
534	    doDifference(left, right, valueEquivalence, onlyOnLeft, onlyOnRight, onBoth, differences);
535	    return new MapDifferenceImpl<>(onlyOnLeft, onlyOnRight, onBoth, differences);
536	  }
