538	  /**
539	   * Computes the difference between two sorted maps, using the comparator of the left map, or
540	   * {@code Ordering.natural()} if the left map uses the natural ordering of its elements. This
541	   * difference is an immutable snapshot of the state of the maps at the time this method is called.
542	   * It will never change, even if the maps change at a later time.
543	   *
544	   * <p>Since this method uses {@code TreeMap} instances internally, the keys of the right map must
545	   * all compare as distinct according to the comparator of the left map.
546	   *
547	   * <p><b>Note:</b>If you only need to know whether two sorted maps have the same mappings, call
548	   * {@code left.equals(right)} instead of this method.
549	   *
550	   * @param left the map to treat as the "left" map for purposes of comparison
551	   * @param right the map to treat as the "right" map for purposes of comparison
552	   * @return the difference between the two maps
553	   * @since 11.0
554	   */
555	  public static <K extends @Nullable Object, V extends @Nullable Object>
556	      SortedMapDifference<K, V> difference(
557	          SortedMap<K, ? extends V> left, Map<? extends K, ? extends V> right) {
558	    checkNotNull(left);
559	    checkNotNull(right);
560	    Comparator<? super K> comparator = orNaturalOrder(left.comparator());
561	    SortedMap<K, V> onlyOnLeft = newTreeMap(comparator);
562	    SortedMap<K, V> onlyOnRight = newTreeMap(comparator);
563	    onlyOnRight.putAll(right); // will whittle it down
564	    SortedMap<K, V> onBoth = newTreeMap(comparator);
565	    SortedMap<K, ValueDifference<V>> differences = newTreeMap(comparator);
566	
567	    doDifference(left, right, Equivalence.equals(), onlyOnLeft, onlyOnRight, onBoth, differences);
568	    return new SortedMapDifferenceImpl<>(onlyOnLeft, onlyOnRight, onBoth, differences);
569	  }
570	
571	  private static <K extends @Nullable Object, V extends @Nullable Object> void doDifference(
572	      Map<? extends K, ? extends V> left,
573	      Map<? extends K, ? extends V> right,
574	      Equivalence<? super @NonNull V> valueEquivalence,
575	      Map<K, V> onlyOnLeft,
576	      Map<K, V> onlyOnRight,
577	      Map<K, V> onBoth,
578	      Map<K, ValueDifference<V>> differences) {
579	    for (Entry<? extends K, ? extends V> entry : left.entrySet()) {
580	      K leftKey = entry.getKey();
581	      V leftValue = entry.getValue();
582	      if (right.containsKey(leftKey)) {
583	        /*
584	         * The cast is safe because onlyOnRight contains all the keys of right.
585	         *
586	         * TODO(cpovirk): Consider checking onlyOnRight.containsKey instead of right.containsKey.
587	         * That could change behavior if the input maps use different equivalence relations (and so
588	         * a key that appears once in `right` might appear multiple times in `left`). We don't
589	         * guarantee behavior in that case, anyway, and the current behavior is likely undesirable.
590	         * So that's either a reason to feel free to change it or a reason to not bother thinking
591	         * further about this.
592	         */
593	        V rightValue = uncheckedCastNullableTToT(onlyOnRight.remove(leftKey));
594	        if (valueEquivalence.equivalent(leftValue, rightValue)) {
595	          onBoth.put(leftKey, leftValue);
596	        } else {
597	          differences.put(leftKey, ValueDifferenceImpl.create(leftValue, rightValue));
598	        }
599	      } else {
600	        onlyOnLeft.put(leftKey, leftValue);
601	      }
602	    }
603	  }
