605	  private static <K extends @Nullable Object, V extends @Nullable Object> Map<K, V> unmodifiableMap(
606	      Map<K, ? extends V> map) {
607	    if (map instanceof SortedMap) {
608	      return Collections.unmodifiableSortedMap((SortedMap<K, ? extends V>) map);
609	    } else {
610	      return Collections.unmodifiableMap(map);
611	    }
612	  }
