614	  private static class MapDifferenceImpl<K extends @Nullable Object, V extends @Nullable Object>
615	      implements MapDifference<K, V> {
616	    final Map<K, V> onlyOnLeft;
617	    final Map<K, V> onlyOnRight;
618	    final Map<K, V> onBoth;
619	    final Map<K, ValueDifference<V>> differences;
620	
621	    MapDifferenceImpl(
622	        Map<K, V> onlyOnLeft,
623	        Map<K, V> onlyOnRight,
624	        Map<K, V> onBoth,
625	        Map<K, ValueDifference<V>> differences) {
626	      this.onlyOnLeft = unmodifiableMap(onlyOnLeft);
627	      this.onlyOnRight = unmodifiableMap(onlyOnRight);
628	      this.onBoth = unmodifiableMap(onBoth);
629	      this.differences = unmodifiableMap(differences);
630	    }
631	
632	    @Override
633	    public boolean areEqual() {
634	      return onlyOnLeft.isEmpty() && onlyOnRight.isEmpty() && differences.isEmpty();
635	    }
636	
637	    @Override
638	    public Map<K, V> entriesOnlyOnLeft() {
639	      return onlyOnLeft;
640	    }
641	
642	    @Override
643	    public Map<K, V> entriesOnlyOnRight() {
644	      return onlyOnRight;
645	    }
646	
647	    @Override
648	    public Map<K, V> entriesInCommon() {
649	      return onBoth;
650	    }
651	
652	    @Override
653	    public Map<K, ValueDifference<V>> entriesDiffering() {
654	      return differences;
655	    }
656	
657	    @Override
658	    public boolean equals(@Nullable Object object) {
659	      if (object == this) {
660	        return true;
661	      }
662	      if (object instanceof MapDifference) {
663	        MapDifference<?, ?> other = (MapDifference<?, ?>) object;
664	        return entriesOnlyOnLeft().equals(other.entriesOnlyOnLeft())
665	            && entriesOnlyOnRight().equals(other.entriesOnlyOnRight())
666	            && entriesInCommon().equals(other.entriesInCommon())
667	            && entriesDiffering().equals(other.entriesDiffering());
668	      }
669	      return false;
670	    }
671	
672	    @Override
673	    public int hashCode() {
674	      return Objects.hash(
675	          entriesOnlyOnLeft(), entriesOnlyOnRight(), entriesInCommon(), entriesDiffering());
676	    }
677	
678	    @Override
679	    public String toString() {
680	      if (areEqual()) {
681	        return "equal";
682	      }
683	
684	      StringBuilder result = new StringBuilder("not equal");
685	      if (!onlyOnLeft.isEmpty()) {
686	        result.append(": only on left=").append(onlyOnLeft);
687	      }
688	      if (!onlyOnRight.isEmpty()) {
689	        result.append(": only on right=").append(onlyOnRight);
690	      }
691	      if (!differences.isEmpty()) {
692	        result.append(": value differences=").append(differences);
693	      }
694	      return result.toString();
695	    }
696	  }
