369	   * Views the array as an immutable list. Copies if the specified range does not cover the complete
370	   * array. Does not check for nulls.
371	   */
372	  static <E> ImmutableList<E> asImmutableList(@Nullable Object[] elements, int length) {
373	    switch (length) {
374	      case 0:
375	        return of();
376	      case 1:
377	        /*
378	         * requireNonNull is safe because the callers promise to put non-null objects in the first
379	         * `length` array elements.
380	         */
381	        @SuppressWarnings("unchecked") // our callers put only E instances into the array
382	        E onlyElement = (E) requireNonNull(elements[0]);
383	        return of(onlyElement);
384	      default:
385	        /*
386	         * The suppression is safe because the callers promise to put non-null objects in the first
387	         * `length` array elements.
388	         */
389	        @SuppressWarnings("nullness")
390	        Object[] elementsWithoutTrailingNulls =
391	            length < elements.length ? Arrays.copyOf(elements, length) : elements;
392	        return new RegularImmutableList<>(elementsWithoutTrailingNulls);
393	    }
